// 这一节点把「筛选条件（在此修改）」里的中文设置解析成"本次运行真正生效的筛选条件"。
// 想确认现在到底用了哪些关键词、分数门槛、时间窗口、时区，直接执行这个节点看输出即可；
// 下游节点（搜索、初筛、打分、汇总）一律读这里的值，不再各自解析原始字符串。
const raw = $input.first().json || {};

// 节点里的框用中文名，方便一眼看懂要改哪个；这里统一映射成英文键，下游只认英文键。
function pick(label, key, fallback) {
  const a = raw[label];
  if (a !== undefined && a !== null && a !== '') return a;
  const b = raw[key];
  if (b !== undefined && b !== null && b !== '') return b;
  return fallback;
}

// 回落值必须和「筛选条件（在此修改）」里显示的数字一致，
// 否则用户把这个框清空后，实际生效的会是另一个值（而且界面上看不出来）。
const DEFAULTS = {
  window_days: 7,
  min_score: 60,
  max_results: 30,
  fetch_pages: 3,
  timezone: 'Asia/Shanghai',
};

const cfg = {
  search_query: pick('搜索词', 'search_query', ''),
  country_code: pick('地区代码', 'country_code', 'hk'),
  language: pick('语言', 'language', 'en'),
  window_days: pick('最近几个日历日', 'window_days', DEFAULTS.window_days),
  min_score: pick('最低匹配分', 'min_score', DEFAULTS.min_score),
  max_results: pick('最多输出几条', 'max_results', DEFAULTS.max_results),
  fetch_pages: pick('抓取页数（每页10条）', 'fetch_pages', DEFAULTS.fetch_pages),
  must_match_keywords: pick('关注关键词', 'must_match_keywords', ''),
  exclude_words: pick('排除词', 'exclude_words', ''),
  company_blacklist: pick('公司黑名单', 'company_blacklist', ''),
  resume_profile: pick('简历与偏好', 'resume_profile', ''),
  timezone: pick('时区', 'timezone', DEFAULTS.timezone),
};

const SEPARATORS = [',', '，', ';', '；', String.fromCharCode(10)];
const JOINER = String.fromCharCode(1);

function toList(value) {
  let text = String(value === null || value === undefined ? '' : value);
  for (let i = 0; i < SEPARATORS.length; i++) {
    text = text.split(SEPARATORS[i]).join(JOINER);
  }
  return text
    .split(JOINER)
    .map(function (s) { return s.trim().toLowerCase(); })
    .filter(function (s) { return s.length > 0; });
}

// 配置问题不再静默：收集成 warnings，下游「全部岗位明细」会写进明细表，用户能直接看到。
const warnings = [];

function toNumber(value, fallback, label) {
  const n = Number(value);
  if (!isFinite(n)) {
    warnings.push(label + ' 不是有效数字，已按 ' + fallback + ' 处理');
    return fallback;
  }
  return n;
}

// ── 时间窗口：按"日历日"算，和 JSearch 的 date_posted 同一口径 ──
// window_days = 3 表示"最近 3 个日历日（含今天）"，即发布日 >= 今天往前 2 天。
let windowDays = Math.round(toNumber(cfg.window_days, DEFAULTS.window_days, '最近几个日历日'));
if (windowDays < 1) {
  warnings.push('最近几个日历日 至少为 1，已按 1 处理');
  windowDays = 1;
}
// 接口只有 today / 3days / week / month 四档，最多约 30 天
const fetchDays = Math.min(30, windowDays);
if (windowDays > 30) {
  warnings.push('最近几个日历日 填了 ' + windowDays + ' 天，但接口最多只往回抓 30 天，更早的岗位抓不到');
}

// ── 分数与条数 ──
const minScore = Math.max(0, Math.min(100, Math.round(toNumber(cfg.min_score, DEFAULTS.min_score, '最低匹配分'))));

let maxResults = Math.round(toNumber(cfg.max_results, DEFAULTS.max_results, '最多输出几条'));
if (maxResults < 1) {
  warnings.push('最多输出几条 至少为 1，已按 1 处理');
  maxResults = 1;
}

// ── 抓取量：和「最多输出几条」分开的两个设置 ──
// JSearch 每页固定 10 条，搜索节点用的是支持 num_pages 的 /search 接口，
// 一次请求把这些页一起拿回来（接口上限 20 页，这里保守取 10 页 = 100 条）。
// 「抓取页数」只决定这轮抓多少条；「最多输出几条」只决定最后入选几条。
// 两者解耦：抓得多但只输出几条是合法组合（多抓才能多机会过门槛），
// 输出条数超过抓取量才需要提醒，否则用户会以为漏写了。
let fetchPages = Math.round(toNumber(cfg.fetch_pages, DEFAULTS.fetch_pages, '抓取页数（每页10条）'));
if (fetchPages < 1) {
  warnings.push('抓取页数 至少为 1，已按 1 页处理');
  fetchPages = 1;
}
if (fetchPages > 10) {
  warnings.push('抓取页数 填了 ' + fetchPages + ' 页，但这里最多只抓 10 页（100 条），已按 10 页处理');
  fetchPages = 10;
}
const fetchEstimate = fetchPages * 10;
if (maxResults > fetchEstimate) {
  warnings.push('最多输出几条 填了 ' + maxResults + ' 条，但本轮只抓 ' + fetchEstimate + ' 条（' + fetchPages + ' 页），实际最多就这么多；想多入选请调大「抓取页数」');
}

// ── 时区 ──
// 发布日期按这个时区换算成"日期"再和窗口比较；非香港用户必须改这里，否则日期边界会差一天。
let timeZone = String(cfg.timezone === null || cfg.timezone === undefined ? '' : cfg.timezone).trim() || DEFAULTS.timezone;
try {
  new Intl.DateTimeFormat('en-CA', { timeZone: timeZone }).format(new Date());
} catch (e) {
  warnings.push('时区 ' + timeZone + ' 无法识别，已改用 ' + DEFAULTS.timezone);
  timeZone = DEFAULTS.timezone;
}

function dateParts(date, tz) {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: tz,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).formatToParts(date);
  const map = {};
  for (const p of parts) map[p.type] = p.value;
  return {
    y: Number(map.year),
    m: Number(map.month),
    d: Number(map.day),
    text: map.year + '-' + map.month + '-' + map.day,
  };
}

const today = dateParts(new Date(), timeZone);

// 最早接受的发布日 = 当地今天往前 (windowDays - 1) 天。
// 例：window_days = 7 → 接受 今天 到 今天-6 这 7 个日历日。
const cutoffDate = new Date(Date.UTC(today.y, today.m - 1, today.d) - (windowDays - 1) * 86400000)
  .toISOString()
  .slice(0, 10);

// 接口档位按"抓取天数"挑最接近的一档，让抓取范围不小于本地判定范围
function datePostedFor(days) {
  if (days <= 1) return 'today';
  if (days <= 3) return '3days';
  if (days <= 7) return 'week';
  return 'month';
}

const datePosted = datePostedFor(fetchDays);

if (windowDays <= 1) {
  warnings.push('窗口设为 1 天时，接口按 UTC 计算今天，当地清晨运行时可能漏掉当天发布的岗位，建议设 2 天以上');
}

// ── 内容条件 ──
const keywords = toList(cfg.must_match_keywords);
const excludeWords = toList(cfg.exclude_words);
const companyBlacklist = toList(cfg.company_blacklist);
const searchQuery = String(cfg.search_query === null || cfg.search_query === undefined ? '' : cfg.search_query).trim();

if (!searchQuery) {
  warnings.push('搜索词为空，本轮不会返回任何职位');
}
if (keywords.length === 0) {
  warnings.push('关注关键词为空，所有职位都会通过初筛（只受排除词和时间窗口限制）');
}

return [{
  json: {
    search_query: searchQuery,
    country_code: String(cfg.country_code || 'hk').trim().toLowerCase(),
    language: String(cfg.language || 'en').trim().toLowerCase(),
    date_posted: datePosted,
    window_days: windowDays,
    fetch_days: fetchDays,
    cutoff_date: cutoffDate,
    cutoff_iso: new Date(Date.now() - windowDays * 86400000).toISOString(),
    min_score: minScore,
    max_results: maxResults,
    num_pages: fetchPages,
    fetch_estimate: fetchEstimate,
    must_match_keywords: keywords,
    exclude_words: excludeWords,
    company_blacklist: companyBlacklist,
    resume_profile: String(cfg.resume_profile === null || cfg.resume_profile === undefined ? '' : cfg.resume_profile).trim(),
    timezone: timeZone,
    warnings: warnings,
  },
}];

// 搜索接口报错时走这条支路：不再让整轮运行悄无声息地结束，
// 而是在明细表里留一行，写清楚是哪一步、什么错误，用户打开表就能看到。
const raw = $input.first().json || {};

let message = '';
try {
  if (raw.error && raw.error.message) message = String(raw.error.message);
  else if (raw.message) message = String(raw.message);
  else message = JSON.stringify(raw).slice(0, 500);
} catch (e) {
  message = '未知错误';
}

let cfg = {};
try { cfg = $('生效筛选条件').first().json || {}; } catch (e) { cfg = {}; }

return [{
  json: {
    run_at: new Date().toISOString(),
    job_id: '',
    title: '',
    company: '',
    location: '',
    posted_at: '',
    url: '',
    stage: '运行异常',
    drop_reason: '搜索接口调用失败（已自动重试）：' + message + '。本轮没有产出，请稍后手动再跑一次。',
    match_score: null,
    passed_min_score: false,
    reasons: '',
    gaps: '',
    tz_label: String(cfg.timezone || 'Asia/Shanghai'),
  },
}];

const cfg = $('生效筛选条件').first().json || {};

// 关键词 / 排除词 / 公司黑名单 / 时间窗口 / 时区都已在「生效筛选条件」解析好，
// 这里只负责把它们逐个套用到职位上，不再读原始配置字符串。

// 时间窗口按"日历日"判定，和 JSearch 的 date_posted 同一口径：
// 发布日不早于 cutoff_date（含当天）就算在窗口内。
const timeZone = String(cfg.timezone || 'Asia/Shanghai');
const windowDays = Number(cfg.window_days) > 0 ? Number(cfg.window_days) : 7;

function localDate(date) {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: timeZone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).formatToParts(date);
  const map = {};
  for (const p of parts) map[p.type] = p.value;
  return map.year + '-' + map.month + '-' + map.day;
}

let cutoffDate = String(cfg.cutoff_date || '').trim();
if (!cutoffDate) {
  // 兜底：配置里没给 cutoff_date 时，按 window_days 从当地今天往前算
  const nowLocal = localDate(new Date());
  const y = Number(nowLocal.slice(0, 4));
  const m = Number(nowLocal.slice(5, 7));
  const d = Number(nowLocal.slice(8, 10));
  cutoffDate = new Date(Date.UTC(y, m - 1, d) - (windowDays - 1) * 86400000).toISOString().slice(0, 10);
}

const mustMatch = Array.isArray(cfg.must_match_keywords) ? cfg.must_match_keywords : [];
const excludeWords = Array.isArray(cfg.exclude_words) ? cfg.exclude_words : [];
const companyBlacklist = Array.isArray(cfg.company_blacklist) ? cfg.company_blacklist : [];

function cleanText(html) {
  return String(html || '')
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/\s+/g, ' ')
    .trim();
}

// ── 关键词匹配规则（全工作流只有这一处实现，改规则只改这里）──
// 英文：按「完整单词 / 完整短语」匹配，并自动兼容单复数。
//   intern      → 命中 intern、interns；不命中 internship、internal、international
//   internship  → 命中 internship、internships
//   sales       → 命中 "Sales Manager"；不命中 Salesforce
//   data analyst→ 命中 "Data Analyst"、"Data-Analyst"、"Data Analysts"
//   结论：intern 和 internship 是两个不同关键词，需要让一组词形互认时用下面两种写法。
//
// 两种可选写法（可以混用，仍用逗号分隔多个条目）：
//   1) 同义词组：竖线隔开，任一命中即算
//        analytics|analytical|analytic      三种写法都算命中
//        recruitment|recruiting|recruit     招人相关词形都算
//   2) 末尾加 * 表示前缀匹配（只认末尾那个星号）
//        recruit*   → 命中 recruit、recruits、recruiting、recruitment、recruiter
//        insight*   → 命中 insight、insights
//      注意：短词别用前缀。intern* 会把 internal、international 一起命中，sales* 会把 Salesforce 命中，
//            这类词请用第 1 种写法逐个列举。
// 中文：仍按「包含」匹配（中文没有词边界），例：数据 命中 数据分析师。
// 排除词：只查标题，不查公司名、不查描述。想按公司名排除，请写进「公司黑名单」。
// 公司黑名单：只查公司名，不查标题、不查描述。
const CJK_CHAR = /[㐀-鿿豈-﫿぀-ヿ]/;

// 英文视图：小写 + 所有非字母数字变空格，再按空格切词。
// 这样 "Data-Analyst" / "Data / Analyst" / "Data  Analyst" 都会切成同样的词序列。
function tokenize(text) {
  return String(text === null || text === undefined ? '' : text)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .split(' ')
    .filter(function (t) { return t.length > 0; });
}

// 单数 ⇄ 复数：列出一个英文单词的所有可能形态
function pluralVariants(word) {
  const w = String(word || '').toLowerCase();
  const forms = [w];
  if (!w) return forms;
  if (/(s|x|z|ch|sh)$/.test(w)) forms.push(w + 'es');
  else if (/[^aeiou]y$/.test(w)) forms.push(w.slice(0, -1) + 'ies');
  else forms.push(w + 's');
  if (/ies$/.test(w)) forms.push(w.slice(0, -3) + 'y');
  else if (/(ses|xes|zes|ches|shes)$/.test(w)) forms.push(w.slice(0, -2));
  else if (/[^s]s$/.test(w)) forms.push(w.slice(0, -1));
  return forms.filter(function (v, i) { return forms.indexOf(v) === i; });
}

// 去掉末尾的星号（前缀写法的记号），其余字符保持原样
function stripStars(text) {
  let out = String(text === null || text === undefined ? '' : text);
  while (out.length > 0 && out.charAt(out.length - 1) === '*') out = out.slice(0, -1);
  return out;
}

// 一条条目 → 一到多条规则：
//   竖线分隔的同义词组会展开成多条规则，任一命中即算（全角竖线也认）
//   含中文的走「包含」，其余按英文整词/短语处理；末尾带 * 的英文词按前缀比对
function compileKeywords(list) {
  const rules = [];
  for (const entry of list) {
    const entryText = String(entry === null || entry === undefined ? '' : entry)
      .toLowerCase()
      .split('｜')
      .join('|')
      .trim();
    if (!entryText) continue;
    for (const part of entryText.split('|')) {
      const keyword = part.trim();
      if (!keyword) continue;
      const isPrefix = keyword.charAt(keyword.length - 1) === '*';
      const body = stripStars(keyword);
      if (CJK_CHAR.test(keyword)) {
        if (body) rules.push({ kind: 'contains', value: body });
        continue;
      }
      const tokens = tokenize(body);
      if (tokens.length === 0) continue;
      const last = tokens[tokens.length - 1];
      rules.push({
        kind: 'words',
        head: tokens.slice(0, -1),
        lastForms: isPrefix ? [] : pluralVariants(last),
        lastPrefix: isPrefix ? last : '',
      });
    }
  }
  return rules;
}

// 整词短语匹配：在词序列里找连续的一段，最后一词按单复数集合比对
function wordRuleHit(rule, tokens) {
  const length = rule.head.length + 1;
  for (let i = 0; i + length <= tokens.length; i++) {
    let matched = true;
    for (let j = 0; j < rule.head.length; j++) {
      if (tokens[i + j] !== rule.head[j]) { matched = false; break; }
    }
    if (!matched) continue;
    const tail = tokens[i + length - 1];
    // 末尾星号的规则按前缀比对，其余按单复数集合比对
    if (rule.lastPrefix ? tail.indexOf(rule.lastPrefix) === 0 : rule.lastForms.indexOf(tail) !== -1) return true;
  }
  return false;
}

function matchesAny(rules, rawText, tokens) {
  for (const rule of rules) {
    if (rule.kind === 'contains') {
      if (rawText.indexOf(rule.value) !== -1) return true;
    } else if (wordRuleHit(rule, tokens)) {
      return true;
    }
  }
  return false;
}

const mustMatchRules = compileKeywords(mustMatch);
const excludeRules = compileKeywords(excludeWords);
const companyRules = compileKeywords(companyBlacklist);

const out = [];
const seenIds = new Set();

// 搜索结果显式从「搜索 JSearch 职位」读，而不是 $input：
// 它后面紧跟着「清空上轮岗位明细」，那个节点只输出一条空结果，
// 用 $input 会把搜索结果顶掉、这里就一条职位都拿不到了。
for (const item of $('搜索 JSearch 职位').all()) {
  const body = item.json || {};
  let jobs = [];

  if (Array.isArray(body.jobs)) {
    jobs = body.jobs;
  } else if (body.data && Array.isArray(body.data.jobs)) {
    jobs = body.data.jobs;
  } else if (Array.isArray(body.data)) {
    jobs = body.data;
  } else if (Array.isArray(body)) {
    jobs = body;
  }

  for (const job of jobs) {
    const jobId = String(job.job_id || job.id || '').trim();
    if (!jobId) continue;

    const title = String(job.job_title || job.title || '').trim();
    const company = String(job.employer_name || job.company || '').trim();
    const location = [job.job_city, job.job_state, job.job_country]
      .filter(function (v) { return !!v; })
      .join(', ') || String(job.job_location || '');
    const description = cleanText(job.job_description || job.description || '');
    const url = job.job_apply_link || job.job_google_link || '';

    let postedAt = '';
    if (job.job_posted_at_datetime_utc) {
      postedAt = String(job.job_posted_at_datetime_utc);
    } else if (job.job_posted_at_timestamp) {
      postedAt = new Date(Number(job.job_posted_at_timestamp) * 1000).toISOString();
    } else if (job.job_posted_at) {
      const parsed = Date.parse(String(job.job_posted_at));
      if (!isNaN(parsed)) postedAt = new Date(parsed).toISOString();
    }

    const postedMs = postedAt ? Date.parse(postedAt) : NaN;
    // 中文按原文包含匹配，英文按词序列整词匹配 —— 两种视图各司其职，不能混用。
    const titleRaw = title.toLowerCase();
    const searchableRaw = (title + ' ' + company + ' ' + description).toLowerCase();
    const searchableTokens = tokenize(title + ' ' + company + ' ' + description);
    const titleTokens = tokenize(title);

    // 不再静默丢弃：每条职位都带上 passed 和 drop_reason。
    // 「只留通过初筛」只放行 passed=true 的，而被砍掉的这一批由
    // 「全部岗位明细」写进记录表，能看到每条到底是哪一条条件把它砍掉的。
    // 判定顺序 = 从"这条职位本身合不合适"到"时间窗口"到"重复"。
    // 时间窗口放在内容条件之后，否则一条不相关的岗位也会被记成"超出窗口"，
    // 把真正该调的关键词盖掉。
    let dropReason = '';
    if (seenIds.has(jobId)) {
      dropReason = '同一批次内重复';
    } else if (mustMatchRules.length > 0 && !matchesAny(mustMatchRules, searchableRaw, searchableTokens)) {
      dropReason = '标题、公司或描述不含关注关键词';
    } else if (matchesAny(excludeRules, titleRaw, titleTokens)) {
      dropReason = '标题命中排除词';
    } else if (matchesAny(companyRules, company.toLowerCase(), tokenize(company))) {
      dropReason = '公司名命中黑名单';
    } else if (!isNaN(postedMs) && localDate(new Date(postedMs)) < cutoffDate) {
      dropReason = '发布日早于窗口起点 ' + cutoffDate;
    }

    seenIds.add(jobId);

    const salaryParts = [job.job_min_salary, job.job_max_salary]
      .filter(function (v) { return v !== null && v !== undefined && v !== ''; });

    out.push({
      json: {
        job_id: jobId,
        title: title,
        company: company,
        location: location,
        posted_at: postedAt,
        url: url,
        salary: salaryParts.join(' - '),
        description: description.slice(0, 2500),
        passed: dropReason === '',
        drop_reason: dropReason,
      },
    });
  }
}

return out;

