const cfg = $('生效筛选条件').first().json || {};
const minScore = Number(cfg.min_score) >= 0 ? Number(cfg.min_score) : 0;
const maxResults = Number(cfg.max_results) > 0 ? Number(cfg.max_results) : 30;

const candidates = $('剔除已推送职位').all();

const FENCE = String.fromCharCode(96);

function stripFence(text) {
  return String(text || '')
    .split(FENCE)
    .join(' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function parseScore(raw) {
  const cleaned = stripFence(raw);
  let parsed = null;
  try {
    parsed = JSON.parse(cleaned);
  } catch (e) {
    const start = cleaned.indexOf('{');
    const end = cleaned.lastIndexOf('}');
    if (start !== -1 && end > start) {
      try { parsed = JSON.parse(cleaned.slice(start, end + 1)); } catch (e2) { parsed = null; }
    }
  }
  if (!parsed || typeof parsed !== 'object') return null;
  const score = Number(parsed.score);
  return {
    score: isNaN(score) ? 0 : Math.max(0, Math.min(100, Math.round(score))),
    reasons: String(parsed.reasons || '').trim(),
    gaps: String(parsed.gaps || '').trim(),
  };
}

// 发布时间统一按配置的时区显示，避免受实例时区影响
const timeZone = String(cfg.timezone || 'Asia/Shanghai');

function formatMinute(value) {
  if (!value) return '未知';
  const parsed = new Date(value);
  if (isNaN(parsed.getTime())) return String(value);
  let parts;
  const opts = {
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
  };
  try {
    parts = new Intl.DateTimeFormat('en-GB', Object.assign({ timeZone: timeZone }, opts)).formatToParts(parsed);
  } catch (e) {
    parts = new Intl.DateTimeFormat('en-GB', opts).formatToParts(parsed);
  }
  const map = {};
  for (const p of parts) map[p.type] = p.value;
  const hour = map.hour === '24' ? '00' : map.hour;
  return map.year + '-' + map.month + '-' + map.day + ' ' + hour + ':' + map.minute;
}

const ranked = [];

for (const item of $input.all()) {
  let index = 0;
  const pairing = item.pairedItem;
  if (typeof pairing === 'number') {
    index = pairing;
  } else if (pairing && typeof pairing === 'object' && typeof pairing.item === 'number') {
    index = pairing.item;
  } else if (Array.isArray(pairing) && pairing[0] && typeof pairing[0].item === 'number') {
    index = pairing[0].item;
  }

  const job = (candidates[index] && candidates[index].json) || {};
  if (!job.job_id) continue;

  const result = parseScore(item.json.text || item.json.response || '');
  if (!result) continue;
  if (result.score < minScore) continue;

  ranked.push({
    job_id: job.job_id,
    title: job.title || '',
    company: job.company || '',
    location: job.location || '',
    posted_at: job.posted_at || '',
    url: job.url || '',
    salary: job.salary || '',
    score: result.score,
    reasons: result.reasons,
    gaps: result.gaps,
  });
}

ranked.sort(function (a, b) { return b.score - a.score; });
const top = ranked.slice(0, maxResults);

return top.map(function (row) {
  const lines = [
    '**公司**：' + (row.company || '未知'),
    '**地点**：' + (row.location || '未知'),
    '**发布时间**：' + (row.posted_at ? formatMinute(row.posted_at) + '（' + timeZone + '）' : '未知'),
    '**匹配分**：' + row.score + ' / 100',
    '**匹配理由**：' + (row.reasons || '无'),
    '**缺口与风险**：' + (row.gaps || '无'),
  ];
  if (row.salary) lines.push('**薪资**：' + row.salary);
  if (row.url) lines.push('', '[查看原始职位并投递](' + row.url + ')');

  return {
    json: {
      job_id: row.job_id,
      title: row.title,
      company: row.company,
      location: row.location,
      posted_at: row.posted_at,
      url: row.url,
      score: row.score,
      reasons: row.reasons,
      gaps: row.gaps,
      page_body: lines.join('\n'),
    },
  };
});

// 这条支路只做一件事：把本轮抓到的每一条职位都留档，
// 连同评分、淘汰原因和是否入选，方便回看"为什么这条没进最终清单"，
// 然后回到「筛选条件（在此修改）」调对应的那一项。
//
// 它直接挂在「归一化并初筛」后面（而不是打分之后），
// 所以"一条都没通过初筛""一条都没抓到"这种最需要排查的轮次，
// 明细表里也一定有内容，不会是被清空后的空白。
// 打分结果用 try/catch 读：没走到打分时读到空，不算错误。
const cfg = $('生效筛选条件').first().json || {};
const minScore = Number(cfg.min_score) >= 0 ? Number(cfg.min_score) : 0;
const maxResults = Number(cfg.max_results) > 0 ? Number(cfg.max_results) : 30;
const windowDays = Number(cfg.window_days) > 0 ? Number(cfg.window_days) : 7;
const cutoffDate = String(cfg.cutoff_date || '');
const warnings = Array.isArray(cfg.warnings) ? cfg.warnings : [];
const runAt = new Date().toISOString();
const FENCE = String.fromCharCode(96);

function parseScore(raw) {
  const text = String(raw || '').split(FENCE).join(' ').trim();
  let parsed = null;
  try {
    parsed = JSON.parse(text);
  } catch (e) {
    const start = text.indexOf('{');
    const end = text.lastIndexOf('}');
    if (start !== -1 && end > start) {
      try { parsed = JSON.parse(text.slice(start, end + 1)); } catch (e2) { parsed = null; }
    }
  }
  if (!parsed || typeof parsed !== 'object') return null;
  const score = Number(parsed.score);
  if (isNaN(score)) return null;
  return {
    score: Math.max(0, Math.min(100, Math.round(score))),
    reasons: String(parsed.reasons || '').trim(),
    gaps: String(parsed.gaps || '').trim(),
  };
}

// 发布时间统一按配置的时区显示
const timeZone = String(cfg.timezone || 'Asia/Shanghai');

function formatMinute(value) {
  if (!value) return '';
  const parsed = new Date(value);
  if (isNaN(parsed.getTime())) return String(value);
  let parts;
  const opts = {
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
  };
  try {
    parts = new Intl.DateTimeFormat('en-GB', Object.assign({ timeZone: timeZone }, opts)).formatToParts(parsed);
  } catch (e) {
    parts = new Intl.DateTimeFormat('en-GB', opts).formatToParts(parsed);
  }
  const map = {};
  for (const p of parts) map[p.type] = p.value;
  const hour = map.hour === '24' ? '00' : map.hour;
  return map.year + '-' + map.month + '-' + map.day + ' ' + hour + ':' + map.minute;
}

function emptyRow(stage, dropReason) {
  return {
    json: {
      run_at: runAt,
      job_id: '',
      title: '',
      company: '',
      location: '',
      posted_at: '',
      url: '',
      stage: stage,
      drop_reason: dropReason,
      match_score: null,
      passed_min_score: false,
      reasons: '',
      gaps: '',
    },
  };
}

const allJobs = $('归一化并初筛').all()
  .map(function (i) { return i.json || {}; })
  .filter(function (j) { return !!j.job_id; });

let deduped = [];
try {
  deduped = $('剔除已推送职位').all().map(function (i) { return i.json || {}; });
} catch (e) {
  deduped = [];
}

let llmOutputs = [];
try {
  llmOutputs = $('DeepSeek 匹配打分').all();
} catch (e) {
  llmOutputs = [];
}

const scoreByJob = {};
for (let i = 0; i < llmOutputs.length; i++) {
  let index = i;
  const pairing = llmOutputs[i].pairedItem;
  if (typeof pairing === 'number') {
    index = pairing;
  } else if (pairing && typeof pairing === 'object' && typeof pairing.item === 'number') {
    index = pairing.item;
  } else if (Array.isArray(pairing) && pairing[0] && typeof pairing[0].item === 'number') {
    index = pairing[0].item;
  }
  const job = deduped[index] || {};
  if (!job.job_id) continue;
  const result = parseScore(llmOutputs[i].json.text || llmOutputs[i].json.response || '');
  if (!result) continue;
  scoreByJob[job.job_id] = result;
}

const dedupedIds = {};
for (const job of deduped) if (job.job_id) dedupedIds[job.job_id] = true;

// 先按分数排出"分数达标的候选"，才能区分"分数够了但被最多输出条数截掉"
const eligible = Object.keys(scoreByJob)
  .map(function (id) { return { job_id: id, score: scoreByJob[id].score }; })
  .filter(function (r) { return r.score >= minScore; })
  .sort(function (a, b) { return b.score - a.score; });

const selectedIds = {};
for (let i = 0; i < Math.min(eligible.length, maxResults); i++) selectedIds[eligible[i].job_id] = true;

const rows = [];

// 一条都没抓到：也留一行，否则用户看到的是一张被清空的表，分不清"没岗位"和"跑坏了"
if (allJobs.length === 0) {
  rows.push(emptyRow('本轮无结果', '搜索接口这次没有返回任何职位。可能原因：搜索词太窄、地区代码与搜索词不匹配、或接口临时异常。'));
}

// 配置问题逐条留痕，方便直接对着改「筛选条件（在此修改）」
for (const w of warnings) {
  rows.push(emptyRow('配置提醒', String(w)));
}

for (const job of allJobs) {
  const result = scoreByJob[job.job_id] || null;
  const score = result ? result.score : null;
  let stage = '';
  let dropReason = '';

  if (job.passed !== true) {
    stage = '初筛淘汰';
    dropReason = job.drop_reason || '未记录原因';
  } else if (!dedupedIds[job.job_id]) {
    stage = '已推送过，本轮跳过';
    dropReason = 'job_seen_jobs 里已有一条记录';
  } else if (!result) {
    stage = '打分未完成';
    dropReason = '大模型没有返回可解析的分数';
  } else if (selectedIds[job.job_id]) {
    stage = '入选';
  } else if (score >= minScore) {
    stage = '分数达标但超出输出条数';
    dropReason = '按分数排序后排在最多 ' + maxResults + ' 条之外';
  } else {
    stage = '未达分数线';
    dropReason = '得分 ' + score + ' 低于门槛 ' + minScore;
  }

  rows.push({
    json: {
      run_at: runAt,
      job_id: job.job_id || '',
      title: job.title || '',
      company: job.company || '',
      location: job.location || '',
      posted_at: formatMinute(job.posted_at),
      url: job.url || '',
      stage: stage,
      drop_reason: dropReason,
      match_score: score,
      passed_min_score: score !== null && score >= minScore,
      reasons: result ? result.reasons : '',
      gaps: result ? result.gaps : '',
      window_info: '最近 ' + windowDays + ' 个日历日，发布日不早于 ' + cutoffDate,
    },
  });
}

return rows;
